import { z } from 'zod';
import { zodResolver } from 'qortex-resource';

const ContactSchema = z.object({
  name: z.string().min(1, 'Name is required'),
  email: z.string().email(),
  company: z.string().optional(),
  tags: z.array(z.string()),
});

type Contact = z.infer<typeof ContactSchema>;

const emptyContact = (): Contact => ({
  name: '',
  email: '',
  company: '',
  tags: [],
});

import { createResource } from 'qortex-resource';

export function createContactResource() {
  return createResource<Contact>({
    key: ['contact', 'new'],
    initialData: emptyContact(),
    validate: { resolver: zodResolver(ContactSchema), on: 'submit' },
    source: {
      save: async (draft) => {
        const created = await api.contacts.create(draft);
        return created;
      },
    },
    onSaveSuccess: (data) => {
      router.push(`/contacts/${data.id}`);
    },
  });
}

export function editContactResource(contactId: string) {
  return createResource<Contact>({
    key: ['contact', contactId],
    validate: { resolver: zodResolver(ContactSchema), on: 'blur' },
    persist: { draft: true, debounce: 400 },
    mutation: { optimistic: true },
    source: {
      fetch: () => api.contacts.get(contactId),
      save: (draft) => api.contacts.update(contactId, draft),
    },
  });
}

import { useResource, useField } from 'qortex-resource-react';

function ContactForm({ contactId }: { contactId?: string }) {
  const isCreate = !contactId;

  const { isLoading, isSaving, isChanged, isValid, save, resource } = useResource({
    key: isCreate ? ['contact', 'new'] : ['contact', contactId],
    initialData: isCreate ? emptyContact() : undefined,
    validate: { resolver: zodResolver(ContactSchema), on: isCreate ? 'submit' : 'blur' },
    persist: isCreate ? undefined : { draft: true },
    source: isCreate
      ? { save: (d) => api.contacts.create(d) }
      : {
          fetch: () => api.contacts.get(contactId!),
          save: (d) => api.contacts.update(contactId!, d),
        },
  });

  if (!isCreate && isLoading) return <p>Loading…</p>;

  return (
    <form onSubmit={(e) => { e.preventDefault(); save(); }}>
      <TextField resource={resource} path="name" label="Name" />
      <TextField resource={resource} path="email" label="Email" />
      <button disabled={!isChanged || !isValid || isSaving}>
        {isCreate ? 'Create' : isSaving ? 'Saving…' : 'Save'}
      </button>
    </form>
  );
}

function TextField({ resource, path, label }) {
  const { value, error, onChange, onBlur } = useField(resource, path);
  return (
    <label>
      {label}
      <input value={value ?? ''} onChange={(e) => onChange(e.target.value)} onBlur={onBlur} />
      {error && <span role="alert">{error}</span>}
    </label>
  );
}
